SELECT a.employee_id, a.meeting_reserve_id, a.meeting_subject, a.meeting_id, m.meeting_name, m.capacity, m.meeting_equipment, a.now_date, a.start_time, a.end_time, a.meeting_status from mee_reserve_audit a LEFT JOIN mee_meeting_manage m ON a.meeting_id = m.id
and a.deleted=0 and a.employee_id = #{param.employeeId}
and a.now_date=#{param.nowDate}
and a.meeting_state=#{param.meetingState}
and a.meeting_status=#{param.meetingStatus}
and a.audit_status=#{param.auditStatus}
order by a.create_time desc,a.start_time desc

SELECT a.employee_id, a.meeting_reserve_id, a.meeting_subject, a.meeting_id, m.meeting_name, m.capacity, m.meeting_equipment, a.now_date, a.start_time, a.end_time, a.meeting_status from mee_reserve_audit a LEFT JOIN mee_meeting_manage m ON a.meeting_id = m.id
and a.deleted=0
and a.meeting_id in
#{item}
and a.now_date=#{param.nowDate}
and a.meeting_state=#{param.meetingState}
and a.meeting_status=#{param.meetingStatus}
and a.meeting_status!=5 and a.meeting_status!=6 and a.review_status=#{param.auditStatus}
order by a.create_time desc,a.start_time desc
